input.newString:
import { getPosts } from '@/lib/api'
import { unstable_cache } from 'next/cache'

const cachedGetPosts = unstable_cache(
  () => getPosts(),
  ['posts'],
  { revalidate: 3600, tags: ['posts'] }
)

export default async function Home() {
  const posts = await cachedGetPosts()

  return (
    <main>
      <h1>Blog Posts</h1>
      <ul>
        {posts.map((post) => (
          <li key={post.id}>
            <h2>{post.title}</h2>
            <p>By {post.author}</p>
          </li>
        ))}
      </ul>
    </main>
  )
}

